Proof.
  exact (@simN_eq l r 5 (Sim_mk true [true; false; false; false] [true; true; true; false; true]) (Sim_mk true [true; false; false; false; false; true; false; false] [true]) ltac:(vm_compute; reflexivity)).
Qed.

