Lemma lsE_00_00011 (l r : side) :
  ((f0 >> f0 >> l) <{{E}} (f0 >> f0 >> f0 >> f1 >> f1 >> r)) -[ tm ]->*
    (l <{{E}} (f0 >> f0 >> f0 >> f1 >> f0 >> f0 >> f0 >> r)).
Proof.
  exact (@simN_eq l r 3
    (Sim_mk true [false; false] [false; false; false; true; true])
    (Sim_mk true [] [false; false; false; true; false; false; false])
