          | OptPureState_none => SweepStep_stop
          end
        | OptList_none => stepLeft0BzLCase2 f b (x :: l3) r rem ahead
        end
      | [] => stepLeft0BzLCase2 f b [] r rem ahead
      end
    end
  end.

