  - (* swL *)
    destruct (peelHead (swL b l l0 :: l1)) as [|l''] eqn:Hp; [exact Hpop |].
    unfold decode; rewrite (peelHead_eq w c _ l'' blank Hp); apply evstep_refl.
  - (* bzL *)
    destruct (peelHead (bzL l l0 :: l1)) as [|l''] eqn:Hp; [exact Hpop |].
    unfold decode; rewrite (peelHead_eq w c _ l'' blank Hp); apply evstep_refl.
