                end)).
  { destruct (advancePureInit 70 l) as [|rem ahead];
      [exact (stepE_1_rest_none_sound w c l r restR Hr) |].
    destruct (callLeftSweepEGo l rem ahead r) as [|st] eqn:Hgo;
      [exact (stepE_1_rest_none_sound w c l r restR Hr) |
