  destruct l1 as [|lc2 l2]; [exact Hsw | destruct lc2; try exact Hsw].
  destruct l2 as [|lc3 l3]; [exact Hsw | destruct lc3; try exact Hsw].
  destruct l3 as [|lc4 l4]; [exact Hsw | destruct lc4; try exact Hsw].
